<?php
require_once __DIR__ . '/../../config/koneksi.php';
require_login(); require_role('laporan');
$pageTitle='Laporan & Rekapitulasi';$activeModule='laporan';
$from=(string)($_GET['dari']??date('Y-m-01'));$to=(string)($_GET['sampai']??date('Y-m-d'));$rt=trim((string)($_GET['rt']??''));$rw=trim((string)($_GET['rw']??''));
foreach(['from','to'] as $dateKey){$value=$$dateKey;if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$value)){if($dateKey==='from')$from=date('Y-m-01');else $to=date('Y-m-d');}}
$filters=['tanggal_laporan BETWEEN ? AND ?'];$params=[$from,$to];
if($rt!==''){$filters[]='w.rt = ?';$params[]=$rt;}if($rw!==''){$filters[]='w.rw = ?';$params[]=$rw;}
$where=implode(' AND ',$filters);
$wasteStmt=$pdo->prepare("SELECT ls.status, COUNT(*) jumlah FROM laporan_sampah ls LEFT JOIN warga w ON w.id_warga=ls.id_warga WHERE $where GROUP BY ls.status ORDER BY ls.status");$wasteStmt->execute($params);$waste=$wasteStmt->fetchAll();
$monthlyStmt=$pdo->prepare("SELECT DATE_FORMAT(ls.tanggal_laporan,'%Y-%m') bulan,COUNT(*) jumlah FROM laporan_sampah ls LEFT JOIN warga w ON w.id_warga=ls.id_warga WHERE $where GROUP BY DATE_FORMAT(ls.tanggal_laporan,'%Y-%m') ORDER BY bulan");$monthlyStmt->execute($params);$monthly=$monthlyStmt->fetchAll();
$wasteTotal=array_sum(array_column($waste,'jumlah'));
$regionFilters=[];$regionParams=[];if($rt!==''){$regionFilters[]='w.rt = ?';$regionParams[]=$rt;}if($rw!==''){$regionFilters[]='w.rw = ?';$regionParams[]=$rw;}$regionWhere=$regionFilters?' AND '.implode(' AND ',$regionFilters):'';
$complaintStmt=$pdo->prepare("SELECT p.status, COUNT(*) jumlah FROM pengaduan p LEFT JOIN warga w ON w.id_warga=p.id_warga WHERE p.tanggal_pengaduan BETWEEN ? AND ?$regionWhere GROUP BY p.status ORDER BY p.status");$complaintStmt->execute(array_merge([$from,$to],$regionParams));$complaints=$complaintStmt->fetchAll();
$violationStmt=$pdo->prepare("SELECT p.status_verifikasi, COUNT(*) jumlah FROM pelanggaran p LEFT JOIN warga w ON w.id_warga=p.id_warga WHERE p.tanggal_kejadian BETWEEN ? AND ?$regionWhere AND p.status_verifikasi IN ('Terverifikasi','Selesai Ditindaklanjuti') GROUP BY p.status_verifikasi ORDER BY p.status_verifikasi");$violationStmt->execute(array_merge([$from,$to],$regionParams));$violations=$violationStmt->fetchAll();
$activityStmt=$pdo->prepare("SELECT judul, tanggal_publikasi FROM berita WHERE status='Terbit' AND DATE(tanggal_publikasi) BETWEEN ? AND ? ORDER BY tanggal_publikasi DESC");$activityStmt->execute([$from,$to]);$activities=$activityStmt->fetchAll();
require __DIR__.'/../template/header.php';require __DIR__.'/../template/sidebar.php';
?><div class="module-heading"><div><span class="eyebrow eyebrow-dark">RINGKASAN DATA</span><h1>Laporan & Rekapitulasi</h1><p>Ringkasan penanganan lingkungan tanpa data pribadi warga.</p></div><a class="btn btn-admin-primary" target="_blank" href="<?= e(base_url('admin/laporan/cetak.php?'.http_build_query($_GET+['dari'=>$from,'sampai'=>$to]))) ?>"><i class="fa-solid fa-print me-2"></i>Cetak laporan</a></div>
<form class="report-filters" method="get"><div><label for="dari">Dari tanggal</label><input class="form-control" type="date" id="dari" name="dari" value="<?= e($from) ?>"></div><div><label for="sampai">Sampai tanggal</label><input class="form-control" type="date" id="sampai" name="sampai" value="<?= e($to) ?>"></div><div><label for="rt">RT</label><input class="form-control" id="rt" name="rt" maxlength="5" value="<?= e($rt) ?>" placeholder="Semua"></div><div><label for="rw">RW</label><input class="form-control" id="rw" name="rw" maxlength="5" value="<?= e($rw) ?>" placeholder="Semua"></div><button class="btn btn-admin-primary" type="submit">Terapkan</button></form>
<div class="report-summary"><article><small>Laporan sampah</small><strong><?= number_format($wasteTotal) ?></strong></article><article><small>Pengaduan warga</small><strong><?= number_format(array_sum(array_column($complaints,'jumlah'))) ?></strong></article><article><small>Dugaan terverifikasi</small><strong><?= number_format(array_sum(array_column($violations,'jumlah'))) ?></strong></article></div>
<section class="admin-panel table-panel mb-3"><div class="panel-heading"><div><h2>Rekap laporan sampah per bulan</h2><p>Jumlah laporan pada periode terpilih</p></div></div><div class="table-responsive"><table class="table admin-table"><thead><tr><th>BULAN</th><th>JUMLAH LAPORAN</th></tr></thead><tbody><?php foreach($monthly as $row):?><tr><td><?=e($row['bulan'])?></td><td><?=(int)$row['jumlah']?></td></tr><?php endforeach;?><?php if(!$monthly):?><tr><td colspan="2" class="table-empty">Belum ada laporan pada periode ini.</td></tr><?php endif;?></tbody></table></div></section>
<div class="dashboard-grid"><section class="admin-panel table-panel"><div class="panel-heading"><div><h2>Penanganan laporan sampah</h2><p><?= e(format_tanggal($from)) ?> – <?= e(format_tanggal($to)) ?></p></div></div><div class="table-responsive"><table class="table admin-table"><thead><tr><th>STATUS</th><th>JUMLAH</th></tr></thead><tbody><?php foreach($waste as $row):?><tr><td><?= e($row['status']) ?></td><td><?= (int)$row['jumlah'] ?></td></tr><?php endforeach;?><?php if(!$waste):?><tr><td colspan="2" class="table-empty">Belum ada data di rentang ini.</td></tr><?php endif;?></tbody></table></div></section><section class="admin-panel table-panel"><div class="panel-heading"><div><h2>Pengaduan warga</h2><p>Rekap berdasarkan status</p></div></div><div class="table-responsive"><table class="table admin-table"><thead><tr><th>STATUS</th><th>JUMLAH</th></tr></thead><tbody><?php foreach($complaints as $row):?><tr><td><?= e($row['status']) ?></td><td><?= (int)$row['jumlah'] ?></td></tr><?php endforeach;?><?php if(!$complaints):?><tr><td colspan="2" class="table-empty">Belum ada pengaduan.</td></tr><?php endif;?></tbody></table></div></section></div>
<div class="dashboard-grid"><section class="admin-panel table-panel"><div class="panel-heading"><div><h2>Dugaan pelanggaran terverifikasi</h2><p>Hanya catatan yang telah diperiksa pengurus</p></div></div><div class="table-responsive"><table class="table admin-table"><thead><tr><th>STATUS VERIFIKASI</th><th>JUMLAH</th></tr></thead><tbody><?php foreach($violations as $row):?><tr><td><?= e($row['status_verifikasi']) ?></td><td><?= (int)$row['jumlah'] ?></td></tr><?php endforeach;?><?php if(!$violations):?><tr><td colspan="2" class="table-empty">Belum ada catatan terverifikasi.</td></tr><?php endif;?></tbody></table></div></section><section class="admin-panel table-panel"><div class="panel-heading"><div><h2>Kegiatan dan informasi</h2><p>Berita terbit pada rentang tanggal</p></div></div><div class="table-responsive"><table class="table admin-table"><thead><tr><th>KEGIATAN / INFORMASI</th><th>TANGGAL</th></tr></thead><tbody><?php foreach($activities as $row):?><tr><td><?= e($row['judul']) ?></td><td><?= e(format_tanggal($row['tanggal_publikasi'])) ?></td></tr><?php endforeach;?><?php if(!$activities):?><tr><td colspan="2" class="table-empty">Belum ada kegiatan terpublikasi.</td></tr><?php endif;?></tbody></table></div></section></div>
<?php require __DIR__.'/../template/footer.php'; ?>